import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, PointLight, DirectionalLight, Box3, Vector3 } = ctx.THREE;

  const container = new Group();
  const activeTimelines = [];
  const activePrimitives = [];

  // 1. BACKDROP (Radial/Vertical Gradient on Stage)
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial();

  // Radial gradient centered slightly offset
  const radialUv = uv().sub(0.5);
  const dist = radialUv.length();
  const bgGrad = mix(
    vec3(0.063, 0.063, 0.090), // #101017
    vec3(0.043, 0.043, 0.063), // #0b0b10
    smoothstep(0.1, 0.9, dist)
  );
  backdropMat.colorNode = bgGrad;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.8);
  container.add(backdrop);

  // Contact Shadow Plane
  const shadowGeo = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    alphaWrite: false,
    depthWrite: false
  });
  const shadowUv = uv().sub(0.5);
  const shadowDist = shadowUv.mul(vec2(1.0, 2.16)).length();
  const shadowAlpha = mix(0.5, 0.0, smoothstep(0.1, 0.5, shadowDist));
  shadowMat.colorNode = vec3(0.04, 0.04, 0.06);
  shadowMat.opacityNode = uniform(shadowAlpha);

  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -1.2, -0.2);
  contactShadow.rotation.x = -Math.PI / 2;
  container.add(contactShadow);

  // 2. ORRERY MECHANISM SUBJECT SETUP
  const gearGroup = new Group();
  container.add(gearGroup);

  // Verified PBR Machined Steel Material
  const steelMat = new MeshPhysicalNodeMaterial({
    color: 0xe8ecf2,
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7
  });

  let primaryGear = new Group();
  let secondaryGear = new Group();
  gearGroup.add(primaryGear);
  gearGroup.add(secondaryGear);

  // Positioning secondary gear coordinates
  secondaryGear.position.set(1.15, 0.35, -0.1);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      // Clean up hierarchy and find actual mesh
      let originalMesh = null;
      gltf.scene.traverse((child) => {
        if (child.isMesh && !originalMesh) {
          originalMesh = child;
        }
      });

      if (originalMesh) {
        // Compute precise bounding box metrics to normalize perfectly
        originalMesh.geometry.computeBoundingBox();
        const box = originalMesh.geometry.boundingBox;
        const sizeX = box.max.x - box.min.x;
        const scaleFit = 1.6 / (sizeX || 1.6);

        // Instantiating Primary Gear Mesh
        const pMesh = originalMesh.clone();
        pMesh.geometry = originalMesh.geometry.clone();
        pMesh.geometry.center(); // absolute origin lock
        pMesh.scale.set(scaleFit, scaleFit, scaleFit);
        pMesh.material = steelMat;
        primaryGear.add(pMesh);

        // Instantiating Secondary Gear Mesh
        const sMesh = originalMesh.clone();
        sMesh.geometry = originalMesh.geometry.clone();
        sMesh.geometry.center();
        const smallScale = scaleFit * (0.9 / 1.6);
        sMesh.scale.set(smallScale, smallScale, smallScale);
        sMesh.material = steelMat;
        secondaryGear.add(sMesh);
      }
    }).catch(err => {
      console.warn("Failed loading Orrery model, using geometry fallbacks:", err);
    });
  }

  // Jewel pivot sphere (MeshPhysicalNodeMaterial) at primary hub center #ff2a38
  const jewelGeo = new SphereGeometry(0.12, 32, 24);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: 0xff2a38,
    transmission: 0.6,
    ior: 1.76,
    roughness: 0.1,
    thickness: 0.2,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8
  });
  const jewelPivot = new Mesh(jewelGeo, jewelMat);
  jewelPivot.position.set(0, 0, 0.1);
  primaryGear.add(jewelPivot);

  // Arbor shafts (ink #16161d cylinders through both hubs)
  const shaftGeo = new CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshStandardNodeMaterial({
    color: 0x16161d,
    roughness: 0.6,
    metalness: 0.4
  });

  const shaftPrimary = new Mesh(shaftGeo, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  shaftPrimary.position.set(0, 0, -0.2);
  primaryGear.add(shaftPrimary);

  const shaftSecondary = new Mesh(shaftGeo, shaftMat);
  shaftSecondary.rotation.x = Math.PI / 2;
  shaftSecondary.position.set(0, 0, -0.2);
  secondaryGear.add(shaftSecondary);

  // 3. LIGHTING RIG
  const lightRig = new Group();

  // Dynamic Rim and Key Lights targeting PBR components
  const keyLight = new DirectionalLight(0xe8ecf2, 1.3);
  keyLight.position.set(4, 5, 3);
  lightRig.add(keyLight);

  const rimLight = new DirectionalLight(0xff2a38, 1.2);
  rimLight.position.set(-4, -2, -1);
  lightRig.add(rimLight);

  const fillLight = new PointLight(0xe8ecf2, 0.5, 10);
  fillLight.position.set(-2, 2, 2);
  lightRig.add(fillLight);

  container.add(lightRig);

  // 4. TYPOGRAPHY ZONE
  const typographyGroup = new Group();
  container.add(typographyGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline' || i.text.length < 25);
  const captionItem = items.find(i => i.role === 'caption' || i.text.length >= 25);

  if (headlineItem) {
    const textH = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 0.30,
      color: '#e8ecf2',
      align: 'center'
    });
    textH.position.set(0, -1.7, 0);
    typographyGroup.add(textH);
  }

  if (captionItem) {
    const textC = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: 0.09,
      color: '#ff2a38',
      align: 'center',
      letterSpacingPx: 0.08
    });
    textC.position.set(0, -2.1, 0);
    typographyGroup.add(textC);
  }

  // 5. ANIMATIONS & ROTATIONS
  const clock = { value: 0 };
  const pulseTimeline = gsap.to(clock, {
    value: 100000,
    duration: 100000,
    ease: "none",
    onUpdate: () => {
      const t = clock.value;
      primaryGear.rotation.z = t * 0.08;
      secondaryGear.rotation.z = 2.45 - (t * 0.142);
    }
  });
  activeTimelines.push(pulseTimeline);

  // Settle transitions
  gsap.fromTo(gearGroup.position, 
    { y: -0.3, z: -0.5 }, 
    { y: 0, z: 0, duration: 1.0, ease: "power3.out" }
  );

  // Apply visual cinematic primitives
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const primResult = ctx.primitives[primitive.name](container, primitive.params);
        if (primResult) {
          activePrimitives.push(primResult);
        }
      }
    }
  }

  // 6. RESOURCE CLEANUP
  container.userData.cleanup = function () {
    activeTimelines.forEach(tl => tl.kill());
    activePrimitives.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });

    steelMat.dispose();
    jewelMat.dispose();
    shaftMat.dispose();
    shadowMat.dispose();
    backdropMat.dispose();
  };

  return container;
}
